/**
 * @name XML External Entity (XXE) injection
 * @description Parsing XML with untrusted input can lead to XXE attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe-injection
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XxeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // XML parsing functions that could be vulnerable to XXE
    exists(API::CallNode call |
      call = API::moduleImport("xml").getMember(["etree", "ElementTree"]).getMember(["parse", "fromstring"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("lxml").getMember(["etree", "ElementTree"]).getMember(["parse", "fromstring"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("defusedxml").getMember(["ElementTree", "minidom", "pulldom", "sax"]).getMember(["parse", "fromstring"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module XxeFlow = TaintTracking::Global<XxeConfig>;
import XxeFlow::PathGraph

from XxeFlow::PathNode source, XxeFlow::PathNode sink
where XxeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XXE vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Code injection via eval/exec
 * @description Using eval or exec with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use API graphs to find eval/exec calls
    exists(API::CallNode call |
      call = API::builtin("eval").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::builtin("exec").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember(["eval", "exec"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "user input"

/**
 * @name SSRF via HTTP requests
 * @description Making HTTP requests with user-controlled URLs could lead to SSRF attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for HTTP request functions
    exists(API::CallNode call |
      call = API::moduleImport("urllib").getMember(["request", "urlopen"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("httplib").getMember(["HTTPConnection", "HTTPSConnection"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability from $@.", source.getNode(), "user input"
